{
	struct virtio_vsock_sock *vvs = vsk->trans;

	/* Cancel close work to avoid a NULL pointer dereference.
	 * Only cancel if it was scheduled, as the work is only
	 * initialized when scheduled.
	 */
	if (vsk->close_work_scheduled)
		cancel_delayed_work_sync(&vsk->close_work);

	kfree(vvs);
	vsk->trans = NULL;
}

